abhinav_6_7 = {
    'hi': '।।7.6--7.7।। श्री अभिनवगुप्त कहते हैं: इन परा और अपरा दो प्रकृतियों से ही सम्पूर्ण भूत उत्पन्न होते हैं; अतः मैं ही समस्त जगत् का उद्भव (सृष्टि) और प्रलय (प्रलयकर्ता) हूँ। हे धनञ्जय ! मुझसे परे कुछ भी अन्य परम कारण नहीं है, यह सम्पूर्ण जगत् मुझमें सूत में मणियों की भाँति पिरोया हुआ है।',
    'en': '7.6--7.7 Sri Abhinavagupta states: All beings arise from these two (Para and Apara) natures; hence I am the origin and dissolution of the entire universe. O Dhananjaya, there is nothing whatsoever higher than Me; all this universe is strung on Me like gems on a thread.',
    'be': '৭.৬--৭.৭ শ্রী অভিনবগুপ্ত বলেছেন: এই পরা ও অপরা দুই প্রকৃতি থেকেই সম্পূর্ণ ভূত উৎপন্ন হয়; অতএব আমিই সমস্ত জগতের উদ্ভব (সৃষ্টি) ও প্রলয় (প্রলয়কর্তা)। হে ধনঞ্জয়! আমা থেকে পরে কিছু অন্য পরম কারণ নেই, এই সম্পূর্ণ জগৎ আমাতে সুতোয় মণির ন্যায় গাঁথা।',
    'ka': '೭.೬--೭.೭ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಈ ಪರಾ ಹಾಗೂ ಅಪರಾ ಎಂಬ ಎರಡು ಪ್ರಕೃತಿಗಳಿಂದಲೇ ಸಮಸ್ತ ಭೂತಗಳೂ ಉತ್ಪನ್ನವಾಗುತ್ತವೆ; ಆದ್ದರಿಂದ ನಾನೇ ಸಮಸ್ತ ಜಗತ್ತಿನ ಉದ್ಭವವೂ (ಸೃಷ್ಟಿ) ಪ್ರಲಯವೂ (ಪ್ರಲಯಕರ್ತ) ಆಗಿದ್ದೇನೆ. ಹೇ ಧನಂಜಯ! ನನ್ನನ್ನು ಹೊರತುಪಡಿಸಿ ಅನ್ಯ ಯಾವ ಪರಮಕಾರಣವೂ ಇಲ್ಲ, ಈ ಸಮಸ್ತ ಜಗತ್ತು ದಾರದಲ್ಲಿ ಮಣಿಗಳಂತೆ ನನ್ನಲ್ಲಿ ಪೋಣಿಸಲ್ಪಟ್ಟಿದೆ'
}

abhinav_8_9 = {
    'hi': '।।7.8--7.9।। श्री अभिनवगुप्त कहते हैं: हे कौन्तेय ! जल में जो रस-मात्र है, सूर्य व चन्द्रमा में जो प्रकाश है, सर्व वेदों में जो ॐकार है, आकाश में जो शब्द और पुरुषों में जो पुरुषत्व है—वह सब मैं ही हूँ। पृथ्वी में जो पवित्र गन्ध और अग्नि में जो तेज है, सर्व भूतों में जो जीवन और तपस्वियों में जो तप है—वह सब मेरा ही स्वरूप है।',
    'en': '7.8--7.9 Sri Abhinavagupta states: O Kaunteya, I am the taste in waters, light in sun and moon, sacred syllable Om in all Vedas, sound in ether, and manhood in men. I am the pure fragrance in earth, brilliance in fire, life in all beings, and austerity in ascetics.',
    'be': '৭.৮--৭.৯ শ্রী অভিনবগুপ্ত বলেছেন: হে কৌন্তেয়! জলে যে রস-মাত্র, সূর্য ও চন্দ্রমাতে যে প্রকাশ, সর্ব বেদে যে ওঁকার, আকাশে যে শব্দ এবং পুরুষদের মধ্যে যে পুরুষত্ব—সে সব আমিই। পৃথিবীতে যে পবিত্র গন্ধ এবং অগ্নিতে যে তেজ, সর্ব ভূতে যে জীবন এবং তপস্বীদের মধ্যে যে তপ—সে সব আমারই রূপ।',
    'ka': '೭.೮--೭.೯ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಹೇ ಕೌಂತೇಯ! ಜಲದಲ್ಲಿ ಯಾವ ರಸಮಾತ್ರವಿದೆಯೋ, ಸೂರ್ಯಚಂದ್ರರಲ್ಲಿ ಯಾವ ಪ್ರಕಾಶವಿದೆಯೋ, ಸರ್ವ ವೇದಗಳಲ್ಲಿ ಯಾವ ಓಂಕಾರವಿದೆಯೋ, ಆಕಾಶದಲ್ಲಿ ಶಬ್ದ ಹಾಗೂ ಪುರುಷರಲ್ಲಿ ಯಾವ ಪುರುಷತ್ವವಿದೆಯೋ—ಆ ಎಲ್ಲವೂ ನಾನೇ ಆಗಿದ್ದೇನೆ. ಪೃಥಿವಿಯಲ್ಲಿ ಯಾವ ಪವಿತ್ರ ಗಂಧವಿದೆಯೋ ಹಾಗೂ ಅಗ್ನಿಯಲ್ಲಿ ಯಾವ ತೇಜಸ್ಸಿನಿದೆಯೋ, ಸರ್ವ ಭೂತಗಳಲ್ಲಿ ಜೀವನ ಹಾಗೂ ತಪಸ್ವಿಗಳಲ್ಲಿ ಯಾವ ತಪಸ್ಸಿನಿದೆಯೋ—ಅದೆಲ್ಲವೂ ನನ್ನದೇ ಸ್ವರೂಪವಾಗಿದೆ'
}

abhinav_10_11 = {
    'hi': '।।7.10--7.11।। श्री अभिनवगुप्त कहते हैं: हे पार्थ ! मुझे सर्व भूतों का सनातन बीज (नित्य कारण) जानो। मैं बुद्धिमानों की बुद्धि और तेजस्वियों का तेज हूँ। बलवानों का काम-राग-रहित बल और सर्व भूतों में धर्म से अविरुद्ध काम मैं ही हूँ।',
    'en': '7.10--7.11 Sri Abhinavagupta states: O Partha, know Me to be the eternal seed of all beings. I am the intellect of the intelligent and splendour of the resplendent. I am the strength of the strong devoid of lust and attachment, and in all beings, desire uncontrary to Dharma.',
    'be': '৭.১০--৭.১১ শ্রী অভিনবগুপ্ত বলেছেন: হে পার্থ! আমাকে সর্ব ভূতের সনাতন বীজ (নিত্য কারণ) জানো। আমি বুদ্ধিমানদের বুদ্ধি এবং তেজস্বীদের তেজ। বলবানদের কাম-রাগ-রহিত বল এবং সর্ব ভূতে ধর্ম থেকে অবিরুদ্ধ কাম আমিই।',
    'ka': '೭.೧೦--೭.೧೧ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಹೇ ಪಾರ್ಥ! ನನ್ನನ್ನು ಸರ್ವ ಭೂತಗಳ ಸನಾತನ ಬೀಜವೆಂದು (ನಿತ್ಯಕಾರಣ) ತಿಳಿಯಿ. ನಾನು ಬುದ್ಧಿವಂತರ ಬುದ್ಧಿ ಹಾಗೂ ತೇಜಸ್ವಿಗಳ ತೇಜಸ್ಸಾಗಿದ್ದೇನೆ. ಬಲವಂತರ ಕಾಮರಾಗರಹಿತ ಬಲವೂ ಸರ್ವ ಭೂತಗಳಲ್ಲಿ ಧರ್ಮಕ್ಕೆ ಅವಿರುದ್ಧವಾದ ಕಾಮವೂ ನಾನೇ ಆಗಿದ್ದೇನೆ'
}

